SELECT SUM(amount) AS gmv
FROM payments
WHERE paid_at >= '2026-09-01' AND paid_at < '2026-10-01';

SELECT ROUND(SUM(amount) / COUNT(DISTINCT order_id), 2) AS avg_order_value
FROM payments
WHERE paid_at >= '2026-06-01' AND paid_at < '2026-07-01';

SELECT COUNT(*) AS user_count
FROM users
WHERE registered_at >= '2025-01-01' AND registered_at < '2025-07-01';

SELECT category, COUNT(*) AS product_count
FROM products
GROUP BY category;

SELECT ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM products), 2) AS pct_over_500
FROM products
WHERE price > 500;
